select extract(year from at) as year, extract(epoch from local_at) as epoch, extract(century from day) as century, extract(decade from wait) as decade, extract(hour from clock) as hour, date_part('YEAR', at) as part_year, date_part('millennium', wait) as part_millennium, extract(month from at) as month, extract(day from day) as day_of_date, extract(day from wait) as day_of_wait, date_part('dow', local_at) as dow from events
